import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>WebP 是现代网页的格式，但设计世界依然靠 PNG 运转。Photoshop、Figma、PowerPoint 和打印店都原生处理 PNG，WebP 的支持还在追赶。</p>\n<p>把 WebP 转成 PNG，就是连接这两个世界的桥梁。像素原样保留，透明度得以保留，转换结果到处都能打开。</p>\n<p>这篇文章会讲设计师为什么转换、PNG 什么时候是正确的目标格式，以及怎么围绕这个转换搭建工作流程。</p>\n<h2 id=\"why-designers-convert\">设计师为什么把 WebP 转成 PNG？</h2>\n<p>设计师从网上下载素材时拿到的是 WebP，因为网站提供的就是这个格式。可他们的设计工具常常更喜欢 PNG，这个标准已经用了几十年。</p>\n<p>Photoshop 加上了 WebP 支持，但很多插件和老流程还是只认 PNG。一个 WebP 文件可能让脚本、批处理或导出预设出问题，这些都是按 PNG 建的。</p>\n<p>Figma 和 Canva 处理 WebP 好一些，但在不同工具之间流转的素材，PNG 依然是更安全的选择。PNG 在每个软件里都能用，WebP 只在大多数软件里能用。</p>\n<p>项目开始时转换一次，就能消除这些摩擦。从那以后每个素材都是 PNG，流程里的任何工具都不会抱怨。</p>\n<h2 id=\"editing-workflow\">以 PNG 为基础的编辑流程</h2>\n<p>先把 WebP 素材转成 PNG。这样就拿到了无损的工作副本，再怎么编辑都不会退化。</p>\n<p>所有编辑都在 PNG 版本上做。裁剪、标注、加文字、调颜色，每次都保存为 PNG，不会再有任何损失。</p>\n<p>把 PNG 母版留在项目文件夹里。它们是设计的唯一真实来源，每次导出都从它们开始。</p>\n<p>完成后再按目的地的要求导出。网页要 WebP 或 JPG，打印店要 PNG，客户演示要 PNG 或 JPG。</p>\n<h2 id=\"transparency-for-designers\">设计师离不开的透明度</h2>\n<p>透明的 WebP 标志转成 PNG 后还是透明的，透明通道和柔和边缘都一样。标志要在很多种背景上使用时，这一点很重要。</p>\n<p>设计师把标志放在白底页面、彩色幻灯片和深色界面上。一张透明 PNG 到处都能用，JPG 却要为每种背景配不同的填充色。</p>\n<p>柔和的阴影和半透明在转换中也得以保留。渐渐淡出的投影在 PNG 里依然平滑过渡。</p>\n<p>使用前用对比查看器检查一下透明度。放大看边缘，确认没有光晕，出现光晕就说明源 WebP 本身有损伤。</p>\n<h2 id=\"compatibility-map\">PNG 兼容性一览</h2>\n<p>Photoshop、Illustrator、Figma、Canva、Sketch 和 Affinity 都原生打开 PNG。不用插件，不用更新，也不用变通办法。</p>\n<p>Word 和 PowerPoint 到处都接受 PNG。粘贴进文档的 PNG 保持锐利的边缘和透明度，截图就该放在 PNG 里。</p>\n<p>打印店和照片冲印店只认 PNG 或 JPG。发给打印机的 PNG 文件马上就能用，WebP 文件却可能被拒，或者被用未知的设置转掉。</p>\n<p>浏览器显示 PNG 毫无问题。有史以来所有浏览器都能显示 PNG，网上分享图片时，它是最安全的格式。</p>\n<h2 id=\"when-png-wins\">PNG 胜过 WebP 的时候</h2>\n<p>图片要编辑时，PNG 赢。无损格式反复保存也不会坏，WebP 每次保存却会多一点损伤。</p>\n<p>目的地不明时，PNG 赢。客户、打印店或用着老软件的同事一定接受 PNG，WebP 却可能被拒。</p>\n<p>截图必须像素级完美时，PNG 赢。法律证据、技术文档和归档图片，都值得 PNG 的精确性。</p>\n<p>图片带锐利文字时，PNG 赢。无损格式让每个字母的边缘都保持清晰，有损 WebP 却会把它们轻微变软。</p>\n<h2 id=\"when-webp-wins\">WebP 胜过 PNG 的时候</h2>\n<p>图片放在网上时，WebP 赢。文件更小，页面加载更快，访客体验和搜索排名都会变好。</p>\n<p>网站上的照片，WebP 赢。PNG 照片比 WebP 版大好几倍，却没有任何肉眼可见的好处，根本不值得多占这些字节。</p>\n<p>图片数量很大的合集，WebP 赢。几百张图的画廊用 WebP 加载快得多，节省的流量也很可观。</p>\n<p>存储吃紧时，WebP 赢。同样的照片存档用 WebP，只占 PNG 存档的一小部分空间。</p>\n<h2 id=\"file-size-reality\">文件大小的现实</h2>\n<p>WebP 照片转成 PNG 会大幅变大，常常是原来的五到十倍。一张 200KB 的 WebP 可能变成 2MB 的 PNG，只期待小幅增长的人会很吃惊。</p>\n<p>细节丰富的照片长得最厉害。每一处纹理像素都必须原样保存，PNG 没办法简化它们。</p>\n<p>简单图形长得少一些。纯色区域多的标志转成的 PNG 不大，因为大面积纯色即使无损压缩效果也很好。</p>\n<p>提前为增长留出预算。一批 WebP 照片转成 PNG 后，ZIP 可能非常大，下载前先看一下总量，确认目的地能不能处理。</p>\n<h2 id=\"colour-and-profiles\">转换中的颜色与色彩配置</h2>\n<p>大多数图片在转换中颜色都保留得很准确。浏览器编码器对常见色彩空间处理得很好，PNG 看起来和 WebP 一样。</p>\n<p>饱和度特别高的颜色可能轻微偏移。现代相机拍的宽色域图片，转成标准 PNG 后可能少一点鲜艳。</p>\n<p>色彩配置可能无法完全保留。PNG 里有看得见的颜色，但 WebP 里嵌的特殊配置可能在转换中被丢掉。</p>\n<p>产品照片这种对颜色敏感的工作，用之前把 PNG 和 WebP 仔细对比一下。偏移通常看不见，但花十秒钟检查一下是值得的。</p>\n<h2 id=\"team-workflows\">围绕转换的团队流程</h2>\n<p>团队从网上下载 WebP 素材时，每个项目开始时先商量好转换这一步。转换一次，把 PNG 放进共享文件夹，之后都用这些文件工作。</p>\n<p>转好的文件起个清楚的名字。logo-main.png 一看就知道是什么，download.webp 却什么都说明不了。</p>\n<p>把 WebP 原件留在归档文件夹里。以后需要导出网页版时，原件还在，不用把 PNG 再转回去。</p>\n<p>把流程写成一页纸的清单。新同事第一天就能照着做，做出和大家一样的结果。</p>\n<h2 id=\"common-mistakes\">常见错误要避开</h2>\n<p>最常见的错误，是把 WebP 照片转成 PNG，指望画质变好。PNG 会原样保留 WebP，瑕疵也一起保留，文件却大得多。</p>\n<p>另一个错误是把整个网站图片库都转成 PNG。PNG 照片比 WebP 大好几倍，页面会变得很慢。</p>\n<p>还有人忘了动态 WebP 转出来会变成静态图。动效很重要的话，根本就别转 PNG。</p>\n<p>最后，别把 WebP 转成 PNG 再转回 WebP，指望省空间。这样来回一趟没有任何好处，还可能带来新的压缩损伤。</p>\n<h2 id=\"decision-guide\">设计师决策指南</h2>\n<p>图片是用来编辑的？转成 PNG，用无损副本来工作。</p>\n<p>图片是用来放网上的？留着 WebP，享受更小的文件。</p>\n<p>图片是用来打印的？用完整分辨率转成 PNG，再检查颜色。</p>\n<p>目的地不明？转成 PNG，兼容性比体积更重要。</p>\n<h2 id=\"png-in-video-editing\">视频编辑中的 PNG</h2>\n<p>视频编辑用 PNG 文件做叠加层、下三分之一字幕和标题卡。透明度让文字和标志能叠在动态视频上，无损画质让边缘保持锐利。</p>\n<p>导入视频编辑器之前，先把 WebP 图形转成 PNG。大多数编辑器原生处理 PNG，视频软件里的 WebP 支持还参差不齐。</p>\n<p>下三分之一字幕按视频分辨率来设计，通常是 1920×1080。这个尺寸的 PNG 叠在画面上很干净，不会出现缩放痕迹。</p>\n<p>转换后检查一下透明度，带白框的视频叠加层看起来就是坏的。导入前用对比查看器确认透明通道还在。</p>\n<p>完成后的视频把 PNG 叠加层一起烧录进去。视频文件本身就带有图形，PNG 只在编辑时需要，交付后就不需要了。</p>\n<h2 id=\"png-in-3d-games\">3D 与游戏素材中的 PNG</h2>\n<p>游戏开发者用 PNG 文件做纹理、精灵图和界面图形。无损画质让细节保持锐利，透明度让精灵图能放在任何背景上。</p>\n<p>导入游戏引擎之前，先把 WebP 纹理转成 PNG。大多数引擎原生处理 PNG，WebP 在不同工具和平台上的支持却不一样。</p>\n<p>精灵图集要保持游戏需要的精确像素尺寸。精灵图放大或缩小会失去锐利的像素感，复古风格的游戏尤其在意这一点。</p>\n<p>手游要注意文件大小，存储空间很重要。PNG 纹理比 WebP 大，引擎支持的话，最终构建可以转成压缩格式。</p>\n<p>把 PNG 母版留在项目仓库里。它们是源素材，每个平台的构建都从它们开始，值得放进版本控制。</p>\n<h2 id=\"png-in-email-signatures\">邮件签名中的 PNG</h2>\n<p>邮件签名里常常带一个小标志，PNG 就是正确的格式。透明度让标志能放在任何邮件背景上，文件小了体积也几乎不重要。</p>\n<p>放进签名之前，先把标志从 WebP 转成 PNG。邮箱客户端显示 PNG 很可靠，WebP 在邮件里的支持还不一致。</p>\n<p>签名标志尽量小，最好在 100KB 以内。每封邮件都带一个大标志既浪费流量又惹人烦，小标志能瞬间加载。</p>\n<p>把标志放在你的网站上，在签名里链接它，而不是作为附件发送。链接的图片从你的服务器加载，邮件本身保持很小。</p>\n<p>全面推广前，在几个邮箱客户端里测试一下签名。在 Gmail、Outlook 和 Apple Mail 里快速看一遍，就能在联系人之前发现破损图片。</p>\n<h2 id=\"png-in-documentation\">文档中的 PNG</h2>\n<p>技术文档里全是截图，PNG 让它们保持可读。手册里的截图要经过多次修订还保持锐利，只有无损格式能保证这一点。</p>\n<p>放进文档之前，先把 WebP 截图转成 PNG。文字保持清晰，图表保持干净，文档看起来很专业。</p>\n<p>把 PNG 截图按章节放进文件夹。每个章节一个文件夹，图片按编号排列，找起来很容易，手册也能按顺序自己组织起来。</p>\n<p>在线文档可以考虑网站上用 WebP，源文件用 PNG。网站提供更小的文件，文档仓库里放无损母版。</p>\n<p>软件变化时更新截图。文档里的过时截图比没有截图更让人困惑，所以每次发布都要检查一遍。</p>\n<h2 id=\"png-in-legal-medical\">法律与医疗影像中的 PNG</h2>\n<p>法律和医疗图片必须保持精确，因为一个像素变了，意思可能就变了。PNG 是正确的格式，因为它无损地保存每个像素。</p>\n<p>归档之前，先把 WebP 证据照片转成 PNG。PNG 原样保存像素，法庭或诊所用的任何软件都能打开。</p>\n<p>医疗扫描绝不能用有损格式。压缩过的扫描可能藏起或编造细节，诊断依赖这张图片时，这是很危险的。</p>\n<p>把原件和 PNG 转换件放在一起保存。法律工作里保管链很重要，原件能证明 PNG 是忠实转换的。</p>\n<p>图片用清楚的名字和日期保存。evidence-2026-11-17.png 这样的文件名，几年后在法庭上还有用，image001.png 就不行了。</p>\n<h2 id=\"png-in-presentations\">演示文稿中的 PNG</h2>\n<p>演示文稿需要锐利的图片，PNG 正好能做到。粘贴进 PowerPoint 的 PNG 截图文字保持清晰，同样截图用 WebP 在老机器上可能直接失败。</p>\n<p>放进演示文稿之前，先把 WebP 图片转成 PNG。PNG 在所有版本的 PowerPoint 里都能干净地嵌入，幻灯片在哪里打开都正常。</p>\n<p>带图表和图形的幻灯片，PNG 是正确的格式。细线和小标签保持可读，投影到大屏幕上也一样。</p>\n<p>转换后看一下整份文稿的大小。超过 50MB 的文稿发邮件或上传都费劲，文件太大就先压缩一下图片。</p>\n<p>演讲前先在演示电脑上测试一下文稿。笔记本上看着正常的幻灯片，在老机器上可能显示破损图片，提前测试就能发现。</p>\n<p>这份指南基本覆盖了所有设计场景。转换是个工具，不是规则，正确的选择取决于图片接下来要去哪里。要转换就打开 <a href=\"/zh/webp-zhuan-png/\">WebP 转 PNG 工具</a>，具体步骤可以看<a href=\"/zh/blog/ruhe-jiang-webp-zhuan-huan-wei-png/\">如何把 WebP 转换成 PNG</a>。完整指南在<a href=\"/zh/blog/webp-zhuan-png-wanquan-zhinan/\">WebP 转 PNG 完全指南</a>里，反方向转换可以用<a href=\"/zh/png-zhuan-webp/\">PNG 转 WebP 工具</a>。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"设计师为什么要在编辑前把 WebP 转成 PNG？","answer":"大多数设计工具原生处理 PNG，WebP 的支持还在追赶，有些插件和批处理操作只认 PNG。项目开始时转换一次，就能拿到无损的工作副本，反复编辑也不会退化。PNG 母版之后就是所有导出的来源。"},{"question":"WebP 转 PNG 能原样保留画质吗？","answer":"转换是原样复制每个像素，PNG 和 WebP 一样好。但如果原来的 WebP 是有损的，它已有的损伤也会一起保留下来，因为 PNG 恢复不了已经丢掉的细节。PNG 之后再怎么保存都不会再变差，这才是真正的好处。"},{"question":"转换后的 PNG 文件能在 Photoshop 和 Figma 里用吗？","answer":"可以。PNG 在 Photoshop、Illustrator、Figma、Canva、Sketch 和 Affinity 里都能原生打开，不用插件也不用变通办法。转换后的 PNG 是标准文件，用起来和别处创建的 PNG 一模一样。"},{"question":"设计师什么时候需要 PNG 而不是 WebP？","answer":"编辑、兼容和打印的时候。PNG 反复保存不会有损，在每个设计工具和办公软件里都能打开，所有打印店都接受。WebP 更小、更适合上网，但 PNG 才是设计用的工作格式。"},{"question":"WebP 文件损坏了或者不是真正的 WebP，会怎么样？","answer":"那张卡片上会显示错误提示，整批里其余的文件会继续转换。先在浏览器里打开这个文件检查一下。如果浏览器里也打不开，文件就是损坏了，需要从源网站重新下载一份。"},{"question":"应该把整个网站图片库都转成 PNG 吗？","answer":"不用。网站图片库转成 PNG 会大好几倍，页面加载会变慢。网站图片留着 WebP，只把需要编辑、打印，或者交给要求 PNG 的工具的特定文件转成 PNG。"}];
